From a5687c644015a097304a2e47476c0ecab2065734 Mon Sep 17 00:00:00 2001
From: Christopher William Snowhill <chris@kode54.net>
Date: Sat, 26 Dec 2020 19:12:32 -0800
Subject: [PATCH] Bluetooth: Fix initializing response id after clearing struct

Looks like this was missed when patching the source to clear the structures
throughout, causing this one instance to clear the struct after the response
id is assigned.

Fixes: eddb7732119d ("Bluetooth: A2MP: Fix not initializing all members")
Signed-off-by: Christopher William Snowhill <chris@kode54.net>
Signed-off-by: Marcel Holtmann <marcel@holtmann.org>

diff --git a/net/bluetooth/a2mp.c b/net/bluetooth/a2mp.c
index da7fd7c8c2dc..cc26e4c047ad 100644
--- a/net/bluetooth/a2mp.c
+++ b/net/bluetooth/a2mp.c
@@ -381,9 +381,9 @@ static int a2mp_getampassoc_req(struct amp_mgr *mgr, struct sk_buff *skb,
 	hdev = hci_dev_get(req->id);
 	if (!hdev || hdev->amp_type == AMP_TYPE_BREDR || tmp) {
 		struct a2mp_amp_assoc_rsp rsp;
-		rsp.id = req->id;

 		memset(&rsp, 0, sizeof(rsp));
+		rsp.id = req->id;

 		if (tmp) {
 			rsp.status = A2MP_STATUS_COLLISION_OCCURED;
-- 
2.25.1

        You will be given the root cause of a bug, the commit message and the corresponding patch.
        You need to extract all code statements that lead to the bug from the patch, based on the root cause and the commit message.

        Root cause:
        The bug was caused by assigning the `req->id` to `rsp.id` before the `rsp` structure was cleared with `memset`. This resulted in the `rsp.id` potentially containing garbage values if the structure was not properly initialized, leading to incorrect behavior in the Bluetooth A2MP response handling.

        Commit message:
        Bluetooth: Fix initializing response id after clearing struct

Looks like this was missed when patching the source to clear the structures
throughout, causing this one instance to clear the struct after the response
id is assigned.

Fixes: eddb7732119d ("Bluetooth: A2MP: Fix not initializing all members")
Signed-off-by: Christopher William Snowhill <chris@kode54.net>
Signed-off-by: Marcel Holtmann <marcel@holtmann.org>  

        Patch:

 static int a2mp_getampassoc_req(struct amp_mgr *mgr, struct sk_buff *skb,
 				struct a2mp_cmd *hdr)
 {
 	struct a2mp_amp_assoc_req *req = (void *) skb->data;
 	struct hci_dev *hdev;
 	struct amp_mgr *tmp;

 	if (le16_to_cpu(hdr->len) < sizeof(*req))
 		return -EINVAL;

 	BT_DBG("id %d", req->id);

 	/* Make sure that other request is not processed */
 	tmp = amp_mgr_lookup_by_state(READ_LOC_AMP_ASSOC);

 	hdev = hci_dev_get(req->id);
 	if (!hdev || hdev->amp_type == AMP_TYPE_BREDR || tmp) {
 		struct a2mp_amp_assoc_rsp rsp;
-		rsp.id = req->id;

 		memset(&rsp, 0, sizeof(rsp));
+		rsp.id = req->id;

 		if (tmp) {
 			rsp.status = A2MP_STATUS_COLLISION_OCCURED;
 			amp_mgr_put(tmp);
 		} else {
 			rsp.status = A2MP_STATUS_INVALID_CTRL_ID;
 		}

 		a2mp_send(mgr, A2MP_GETAMPASSOC_RSP, hdr->ident, sizeof(rsp),
 			  &rsp);

 		goto done;
 	}

 	amp_read_loc_assoc(hdev, mgr);

 done:
 	if (hdev)
 		hci_dev_put(hdev);

 	skb_pull(skb, sizeof(*req));
 	return 0;
 }



        Provide a response strictly in the following format:
        Code statements:
        <text1>
        <text2>
        ...
        <textN>

Code statements:
- rsp.id = req->id;
+ rsp.id = req->id;

Code statements:
- rsp.id = req->id;
+ rsp.id = req->id;
